using System;
using System.Collections.Generic;
using Game.Cards;
using Game.Map;
using UnityEngine;

namespace Game.Saves
{
    // Generated by MatchSaveAssetManifestBuilder before entering play and before every build.
    // References keep the same GUID/local-file identity when assets are renamed or reordered.
    public sealed class MatchSaveAssetManifest : ScriptableObject
    {
        public string ContentFingerprint;
        public List<MatchSaveSpriteAsset> Sprites = new List<MatchSaveSpriteAsset>();
        public List<MatchSaveMaterialAsset> Materials = new List<MatchSaveMaterialAsset>();
        public List<MatchSavePrefabAsset> Prefabs = new List<MatchSavePrefabAsset>();
        public List<EventCatalog> EventCatalogs = new List<EventCatalog>();
    }
    [Serializable] public sealed class MatchSaveSpriteAsset { public string Key; public Sprite Asset; }
    [Serializable] public sealed class MatchSaveMaterialAsset { public string Key; public Material Asset; }
    [Serializable] public sealed class MatchSavePrefabAsset { public string Key; public MapObjectVisual Asset; }

    internal static class MatchSaveAssets
    {
        private const string ResourceName = "MatchSaveAssetManifest";
        private static MatchSaveAssetManifest Manifest => Resources.Load<MatchSaveAssetManifest>(ResourceName)
            ?? throw new InvalidOperationException("Missing generated match save content manifest. Reimport the project before building.");
        internal static string ContentFingerprint
        {
            get
            {
                string value = Manifest.ContentFingerprint;
                if (string.IsNullOrEmpty(value) || value.Length != 64) throw new InvalidOperationException("Invalid match content fingerprint.");
                return value;
            }
        }
        internal static string SpriteKey(Sprite asset)
        {
            if (asset == null) return null;
            string result = null;
            foreach (var entry in Manifest.Sprites)
                if (entry != null && entry.Asset == asset)
                {
                    if (result != null && result != entry.Key) throw new InvalidOperationException("Ambiguous sprite asset identity.");
                    result = entry.Key;
                }
            return result ?? throw new InvalidOperationException("Sprite is not in the authored match content manifest.");
        }
        internal static Sprite ResolveSprite(string key)
        {
            if (string.IsNullOrEmpty(key)) return null;
            Sprite result = null;
            foreach (var entry in Manifest.Sprites)
                if (entry != null && entry.Key == key)
                {
                    if (result != null) throw new ArgumentException("Duplicate sprite asset identity: " + key);
                    result = entry.Asset;
                }
            return result != null ? result : throw new ArgumentException("Unresolved authored sprite: " + key);
        }
        internal static string MaterialKey(Material asset)
        {
            if (asset == null) return null;
            string result = null;
            foreach (var entry in Manifest.Materials)
                if (entry != null && entry.Asset == asset)
                {
                    if (result != null && result != entry.Key) throw new InvalidOperationException("Ambiguous material asset identity.");
                    result = entry.Key;
                }
            return result ?? throw new InvalidOperationException("Material is not in the authored match content manifest.");
        }
        internal static Material ResolveMaterial(string key)
        {
            if (string.IsNullOrEmpty(key)) return null;
            Material result = null;
            foreach (var entry in Manifest.Materials)
                if (entry != null && entry.Key == key)
                {
                    if (result != null) throw new ArgumentException("Duplicate material asset identity: " + key);
                    result = entry.Asset;
                }
            return result != null ? result : throw new ArgumentException("Unresolved authored material: " + key);
        }
        internal static string PrefabKey(MapObjectVisual asset)
        {
            if (asset == null) return null;
            string result = null;
            foreach (var entry in Manifest.Prefabs)
                if (entry != null && entry.Asset == asset)
                {
                    if (result != null && result != entry.Key) throw new InvalidOperationException("Ambiguous marker prefab identity.");
                    result = entry.Key;
                }
            return result ?? throw new InvalidOperationException("Marker prefab is not in the authored match content manifest.");
        }
        internal static MapObjectVisual ResolvePrefab(string key)
        {
            if (string.IsNullOrEmpty(key)) return null;
            MapObjectVisual result = null;
            foreach (var entry in Manifest.Prefabs)
                if (entry != null && entry.Key == key)
                {
                    if (result != null) throw new ArgumentException("Duplicate marker prefab identity: " + key);
                    result = entry.Asset;
                }
            return result != null ? result : throw new ArgumentException("Unresolved authored marker prefab: " + key);
        }
        internal static EventDefinition ResolveEvent(string key)
        {
            if (string.IsNullOrEmpty(key)) throw new ArgumentException("Missing event authored key.");
            EventDefinition found = null;
            foreach (var catalog in Manifest.EventCatalogs)
            {
                var entry = catalog != null ? catalog.ResolveEvent(key) : null;
                if (entry == null) continue;
                if (found != null && !ReferenceEquals(found, entry)) throw new ArgumentException("Duplicate event authored key: " + key);
                found = entry;
            }
            return found ?? throw new ArgumentException("Unresolved authored event: " + key);
        }
        internal static string EventKey(EventDefinition value)
        {
            if (value == null || !ReferenceEquals(ResolveEvent(value.authoredKey), value))
                throw new ArgumentException("Event does not belong to the authored content manifest.");
            return value.authoredKey;
        }
    }
}
